pub fn auth_signed_in_count(count: u64) -> String {
    let args: &[(&str, &dyn std::fmt::Display)] = &[("count", &count)];
    match locale() {
        Locale::En => match cardinal(Locale::En, count) {
            Category::One => fill("{count} account signed in on this device", args),
            _ => fill("{count} accounts signed in on this device", args),
        },
        Locale::De => match cardinal(Locale::De, count) {
            Category::One => fill("{count} Konto auf diesem Gerät angemeldet", args),
            _ => fill("{count} Konten auf diesem Gerät angemeldet", args),
        },
        Locale::Fr => match cardinal(Locale::Fr, count) {
            Category::One => fill("{count} compte connecté sur cet appareil", args),
            _ => fill("{count} comptes connectés sur cet appareil", args),
        },
        Locale::Pt => match count {
            1 => fill("{count} conta com sessão iniciada neste dispositivo", args),
            _ => fill("{count} contas com sessão iniciada neste dispositivo", args),
        },
    }
}
