pub fn cal_sys_offline_pending(since: impl std::fmt::Display, count: u64) -> String {
    let args: &[(&str, &dyn std::fmt::Display)] = &[("since", &since), ("count", &count)];
    match locale() {
        Locale::En => match cardinal(Locale::En, count) {
            Category::One => fill(
                "Offline since {since}. {count} local change is waiting; nothing has been lost.",
                args,
            ),
            _ => fill(
                "Offline since {since}. {count} local changes are waiting; nothing has been lost.",
                args,
            ),
        },
        Locale::De => match cardinal(Locale::De, count) {
            Category::One => fill(
                "Seit {since} offline. {count} lokale Änderung wartet; nichts ist verloren gegangen.",
                args,
            ),
            _ => fill(
                "Seit {since} offline. {count} lokale Änderungen warten; nichts ist verloren gegangen.",
                args,
            ),
        },
        Locale::Fr => match cardinal(Locale::Fr, count) {
            Category::One => fill(
                "Hors ligne depuis {since}. {count} modification locale est en attente ; rien n’a été perdu.",
                args,
            ),
            _ => fill(
                "Hors ligne depuis {since}. {count} modifications locales sont en attente ; rien n’a été perdu.",
                args,
            ),
        },
        Locale::Pt => match count {
            1 => fill(
                "Sem ligação desde {since}. {count} alteração local está em espera; nada se perdeu.",
                args,
            ),
            _ => fill(
                "Sem ligação desde {since}. {count} alterações locais estão em espera; nada se perdeu.",
                args,
            ),
        },
    }
}
