pub fn lc_grace_detail(
    count: u64,
    suspend: impl std::fmt::Display,
    remove: impl std::fmt::Display,
) -> String {
    let args: &[(&str, &dyn std::fmt::Display)] = &[
        ("count", &count),
        ("suspend", &suspend),
        ("remove", &remove),
    ];
    match locale() {
        Locale::En => match cardinal(Locale::En, count) {
            Category::One => fill(
                "Becomes inactive {suspend} · {count} days left · your mail is safe until {remove}.",
                args,
            ),
            _ => fill(
                "Becomes inactive {suspend} · {count} days left · your mail is safe until {remove}.",
                args,
            ),
        },
        Locale::De => match cardinal(Locale::De, count) {
            Category::One => fill(
                "Wird am {suspend} inaktiv · noch {count} Tag · Ihre E-Mails bleiben bis {remove} erhalten.",
                args,
            ),
            _ => fill(
                "Wird am {suspend} inaktiv · noch {count} Tage · Ihre E-Mails bleiben bis {remove} erhalten.",
                args,
            ),
        },
        Locale::Fr => match cardinal(Locale::Fr, count) {
            Category::One => fill(
                "Devient inactif {suspend} · {count} jour restant · vos e-mails sont conservés jusqu’au {remove}.",
                args,
            ),
            _ => fill(
                "Devient inactif {suspend} · {count} jours restants · vos e-mails sont conservés jusqu’au {remove}.",
                args,
            ),
        },
        Locale::Pt => match count {
            1 => fill(
                "Fica inativa em {suspend} · falta {count} dia · as suas mensagens estão seguras até {remove}.",
                args,
            ),
            _ => fill(
                "Fica inativa em {suspend} · faltam {count} dias · as suas mensagens estão seguras até {remove}.",
                args,
            ),
        },
    }
}
