pub fn mail_alerts_dns_detail_more(domain: impl std::fmt::Display, count: u64) -> Rich {
    let args: &[(&str, &dyn std::fmt::Display)] = &[("domain", &domain), ("count", &count)];
    match locale() {
        Locale::En => match cardinal(Locale::En, count) {
            Category::One => Rich::template(
                "Records for <mono>{domain}</mono> and {count} more domain no longer resolve. Mail may be rejected or marked as spam.",
                args,
            ),
            _ => Rich::template(
                "Records for <mono>{domain}</mono> and {count} more domains no longer resolve. Mail may be rejected or marked as spam.",
                args,
            ),
        },
        Locale::De => match cardinal(Locale::De, count) {
            Category::One => Rich::template(
                "Einträge für <mono>{domain}</mono> und {count} weitere Domain lassen sich nicht mehr auflösen. E-Mails könnten abgewiesen oder als Spam eingestuft werden.",
                args,
            ),
            _ => Rich::template(
                "Einträge für <mono>{domain}</mono> und {count} weitere Domains lassen sich nicht mehr auflösen. E-Mails könnten abgewiesen oder als Spam eingestuft werden.",
                args,
            ),
        },
        Locale::Fr => match cardinal(Locale::Fr, count) {
            Category::One => Rich::template(
                "Les enregistrements de <mono>{domain}</mono> et de {count} autre domaine ne sont plus résolus. Les e-mails risquent d’être rejetés ou marqués comme indésirables.",
                args,
            ),
            _ => Rich::template(
                "Les enregistrements de <mono>{domain}</mono> et de {count} autres domaines ne sont plus résolus. Les e-mails risquent d’être rejetés ou marqués comme indésirables.",
                args,
            ),
        },
        Locale::Pt => match count {
            1 => Rich::template(
                "Os registos de <mono>{domain}</mono> e de mais {count} domínio já não são resolvidos. As mensagens poderão ser rejeitadas ou marcadas como spam.",
                args,
            ),
            _ => Rich::template(
                "Os registos de <mono>{domain}</mono> e de mais {count} domínios já não são resolvidos. As mensagens poderão ser rejeitadas ou marcadas como spam.",
                args,
            ),
        },
    }
}
