pub fn mail_dirfail_lede(name: impl std::fmt::Display) -> Rich {
    let args: &[(&str, &dyn std::fmt::Display)] = &[("name", &name)];
    match locale() {
        Locale::En => Rich::template(
            "Thelemail couldn't trust what the server asserted about <b>{name}</b>. This isn't the same as \"recipient not found\". The account probably exists, but the signed record binding their address to a key didn't hold up. So nothing was encrypted, and nothing was sent.",
            args,
        ),
        Locale::De => Rich::template(
            "Thelemail konnte den Angaben des Servers zu <b>{name}</b> nicht vertrauen. Das ist nicht dasselbe wie „Empfänger nicht gefunden“. Das Konto existiert wahrscheinlich, aber der signierte Eintrag, der seine Adresse mit einem Schlüssel verknüpft, bestand die Prüfung nicht. Deshalb wurde nichts verschlüsselt und nichts gesendet.",
            args,
        ),
        Locale::Fr => Rich::template(
            "Thelemail n’a pas pu se fier aux informations du serveur concernant <b>{name}</b>. Il ne s’agit pas d’un destinataire introuvable : le compte existe probablement, mais l’entrée signée associant son adresse à une clé n’a pas pu être validée. Rien n’a donc été chiffré ni envoyé.",
            args,
        ),
        Locale::Pt => Rich::template(
            "O Thelemail não conseguiu confiar no que o servidor declarou sobre <b>{name}</b>. Não é o mesmo que «destinatário não encontrado». A conta provavelmente existe, mas o registo assinado que associa o endereço a uma chave não foi validado. Por isso, nada foi cifrado nem enviado.",
            args,
        ),
    }
}
