pub fn settings_account_price_month(price: impl std::fmt::Display) -> String {
    let args: &[(&str, &dyn std::fmt::Display)] = &[("price", &price)];
    match locale() {
        Locale::En => fill("{price} / month", args),
        Locale::De => fill("{price} / Monat", args),
        Locale::Fr => fill("{price} / mois", args),
        Locale::Pt => fill("{price} / mês", args),
    }
}
pub fn settings_account_price_seats_month(
    count: u64,
    price: impl std::fmt::Display,
    total: impl std::fmt::Display,
) -> String {
    let args: &[(&str, &dyn std::fmt::Display)] =
        &[("count", &count), ("price", &price), ("total", &total)];
    match locale() {
        Locale::En => match cardinal(Locale::En, count) {
            Category::One => fill("{price} × {count} mailbox = {total} / month", args),
            _ => fill("{price} × {count} mailboxes = {total} / month", args),
        },
        Locale::De => match cardinal(Locale::De, count) {
            Category::One => fill("{price} × {count} Postfach = {total} / Monat", args),
            _ => fill("{price} × {count} Postfächer = {total} / Monat", args),
        },
        Locale::Fr => match cardinal(Locale::Fr, count) {
            Category::One => fill("{price} × {count} boîte mail = {total} / mois", args),
            _ => fill("{price} × {count} boîtes mail = {total} / mois", args),
        },
        Locale::Pt => match count {
            1 => fill("{price} × {count} caixa de correio = {total} / mês", args),
            _ => fill("{price} × {count} caixas de correio = {total} / mês", args),
        },
    }
}
