pub fn settings_domains_lapse_note(
    domain: impl std::fmt::Display,
    since: impl std::fmt::Display,
    deadline: impl std::fmt::Display,
) -> Rich {
    let args: &[(&str, &dyn std::fmt::Display)] = &[
        ("domain", &domain),
        ("since", &since),
        ("deadline", &deadline),
    ];
    match locale() {
        Locale::En => Rich::template(
            "The ownership TXT record for <b>{domain}</b> has been missing since {since}. Restore it by {deadline}, or the domain will be released and its addresses will stop working.",
            args,
        ),
        Locale::De => Rich::template(
            "Der TXT-Eintrag für die Inhaberschaft von <b>{domain}</b> fehlt seit {since}. Stellen Sie ihn bis {deadline} wieder her, sonst wird die Domain freigegeben und ihre Adressen funktionieren nicht mehr.",
            args,
        ),
        Locale::Fr => Rich::template(
            "L’enregistrement TXT de propriété de <b>{domain}</b> est absent depuis le {since}. Rétablissez-le avant le {deadline}, sinon le domaine sera libéré et ses adresses cesseront de fonctionner.",
            args,
        ),
        Locale::Pt => Rich::template(
            "O registo TXT de propriedade de <b>{domain}</b> está em falta desde {since}. Reponha-o até {deadline}, caso contrário o domínio será libertado e os seus endereços deixarão de funcionar.",
            args,
        ),
    }
}
